// 命令上下文先保留原错误与提供人，等领域守卫走到Interaction.validate时再报告，不抢未知来源/能力首错。
InteractionContext command_context(const BoundaryValue* value){InteractionContext out;if(!value||!value->as<BoundaryValue::Dict>()){out.input_error="MissingInteractionContext";return out;}auto copy=[&](const char* key,StableId& target){if(const auto* field=value->find(key))if(const auto* text=field->as<StableId>())target=*text;};copy("place_id",out.place_id);copy("provider_actor_id",out.provider_actor_id);copy("role_id",out.role_id);if(const auto* kind=value->find("kind"))if(const auto* name=kind->as<StableId>();name&&*name=="encounter"){out.kind=*name;if(const auto* id=value->find("encounter_id"))if(const auto* text=id->as<StableId>())out.encounter_id=*text;return out;}try{return interaction_codec::decode_context(*value,"params/context");}catch(const boundary::DecodeFailure&){out.input_error="InvalidInteractionContext";return out;}}
// 逐项解析policy的固定字段，拒绝未知附加状态。
FamilyPolicy policy(const BoundaryValue& v){fields(v,{"child_age_years","guardian_min_age","heir_min_age","retirement_min_age"},{"enable_travel_plan"},"policy");FamilyPolicy r;r.child_age_years=get_int(v,"child_age_years","policy");r.guardian_min_age=get_int(v,"guardian_min_age","policy");r.heir_min_age=get_int(v,"heir_min_age","policy");r.retirement_min_age=get_int(v,"retirement_min_age","policy");if(auto* p=v.find("enable_travel_plan"))r.enable_travel_plan=boolean(*p,"policy/enable_travel_plan");r.field_order=order(v);return r;}
// 保留policy的原字典顺序和可选字段存在性。
Status emit_policy(ProjectionWriter& out,const FamilyPolicy& r){out.field("child_age_years",r.child_age_years);out.field("guardian_min_age",r.guardian_min_age);out.field("heir_min_age",r.heir_min_age);out.field("retirement_min_age",r.retirement_min_age);if(r.enable_travel_plan)out.field("enable_travel_plan",*r.enable_travel_plan);return out.order_fields(r.field_order);}
BoundaryValue encode_policy(const FamilyPolicy& r){return family_projection::encode([&](auto& out){return emit_policy(out,r);});}
// 逐项解析terms的固定字段，拒绝未知附加状态。
AdoptionTerms terms(const BoundaryValue& v){fields(v,{"guardian_actor_id","provider_actor_id","role_id","place_id","prototype_id","display_name","birth_tick","duration","fee","payer_wallet_id","recipient_wallet_id","policy"},{},"terms");AdoptionTerms r;r.guardian_actor_id=get_string(v,"guardian_actor_id","terms");r.provider_actor_id=get_string(v,"provider_actor_id","terms");r.role_id=get_string(v,"role_id","terms");r.place_id=get_string(v,"place_id","terms");r.prototype_id=get_string(v,"prototype_id","terms");r.display_name=get_string(v,"display_name","terms");r.birth_tick=get_int(v,"birth_tick","terms");r.duration=get_int(v,"duration","terms");r.fee=get_int(v,"fee","terms");r.payer_wallet_id=get_string(v,"payer_wallet_id","terms");r.recipient_wallet_id=get_string(v,"recipient_wallet_id","terms");r.policy=policy(field(v,"policy","terms"));r.field_order=order(v);return r;}
// 保留terms的原字典顺序和可选字段存在性。
Status emit_terms(ProjectionWriter& out,const AdoptionTerms& r){out.field("guardian_actor_id",r.guardian_actor_id);out.field("provider_actor_id",r.provider_actor_id);out.field("role_id",r.role_id);out.field("place_id",r.place_id);out.field("prototype_id",r.prototype_id);out.field("display_name",r.display_name);out.field("birth_tick",r.birth_tick);out.field("duration",r.duration);out.field("fee",r.fee);out.field("payer_wallet_id",r.payer_wallet_id);out.field("recipient_wallet_id",r.recipient_wallet_id);out.object("policy",[&](auto& w){return emit_policy(w,r.policy);});return out.order_fields(r.field_order);}
BoundaryValue encode_terms(const AdoptionTerms& r){return family_projection::encode([&](auto& out){return emit_terms(out,r);});}
// 逐项解析wallet的固定字段，拒绝未知附加状态。
SuccessionWallet wallet(const BoundaryValue& v){fields(v,{"source_id","destination_id","amount"},{},"wallet");SuccessionWallet r;r.source_id=get_string(v,"source_id","wallet");r.destination_id=get_string(v,"destination_id","wallet");r.amount=get_int(v,"amount","wallet");r.field_order=order(v);return r;}
// 保留wallet的原字典顺序和可选字段存在性。
Status emit_wallet(ProjectionWriter& out,const SuccessionWallet& r){out.field("source_id",r.source_id);out.field("destination_id",r.destination_id);out.field("amount",r.amount);return out.order_fields(r.field_order);}
// 逐项解析goods的固定字段，拒绝未知附加状态。
SuccessionGoods goods(const BoundaryValue& v){fields(v,{"source_inventory_id","destination_inventory_id","lot_id","item_id","quantity"},{},"goods");SuccessionGoods r;r.source_inventory_id=get_string(v,"source_inventory_id","goods");r.destination_inventory_id=get_string(v,"destination_inventory_id","goods");r.lot_id=get_string(v,"lot_id","goods");r.item_id=get_string(v,"item_id","goods");r.quantity=get_int(v,"quantity","goods");r.field_order=order(v);return r;}
// 保留goods的原字典顺序和可选字段存在性。
Status emit_goods(ProjectionWriter& out,const SuccessionGoods& r){out.field("source_inventory_id",r.source_inventory_id);out.field("destination_inventory_id",r.destination_inventory_id);out.field("lot_id",r.lot_id);out.field("item_id",r.item_id);out.field("quantity",r.quantity);return out.order_fields(r.field_order);}
// 逐项解析estate的固定字段，拒绝未知附加状态。
SuccessionEstate estate(const BoundaryValue& v){fields(v,{"estate_id","inventory_id","wallet_id"},{},"estate");SuccessionEstate r;r.estate_id=get_string(v,"estate_id","estate");r.inventory_id=get_string(v,"inventory_id","estate");r.wallet_id=get_string(v,"wallet_id","estate");r.field_order=order(v);return r;}
// 保留estate的原字典顺序和可选字段存在性。
Status emit_estate(ProjectionWriter& out,const SuccessionEstate& r){out.field("estate_id",r.estate_id);out.field("inventory_id",r.inventory_id);out.field("wallet_id",r.wallet_id);return out.order_fields(r.field_order);}
// 继任按原列表保序，金额与物资记录不以当前余额替代历史来源。
SuccessionAssets assets(const BoundaryValue& v){fields(v,{"wallets","goods","estates","disabled_roles"},{},"assets");SuccessionAssets r;for(const auto& x:array(field(v,"wallets","assets"),"assets/wallets"))r.wallets.push_back(wallet(x));for(const auto& x:array(field(v,"goods","assets"),"assets/goods"))r.goods.push_back(goods(x));for(const auto& x:array(field(v,"estates","assets"),"assets/estates"))r.estates.push_back(estate(x));r.disabled_roles=strings(field(v,"disabled_roles","assets"),"assets/disabled_roles");r.field_order=order(v);return r;}
// 历史账目输出独立值，不把钱包和物资引用泄漏给前端。
Status emit_assets(ProjectionWriter& out,const SuccessionAssets& r){out.sequence("wallets",r.wallets,[](auto& w,const auto& v){return w.object("",[&](auto& p){return emit_wallet(p,v);});});out.sequence("goods",r.goods,[](auto& w,const auto& v){return w.object("",[&](auto& p){return emit_goods(p,v);});});out.sequence("estates",r.estates,[](auto& w,const auto& v){return w.object("",[&](auto& p){return emit_estate(p,v);});});out.sequence("disabled_roles",r.disabled_roles,[](auto& w,const auto& v){return w.field("",v);});return out.order_fields(r.field_order);}
BoundaryValue encode_assets(const SuccessionAssets& r){return family_projection::encode([&](auto& out){return emit_assets(out,r);});}
// 报价不附kind/tick；事实含永久时刻，字段添加顺序保持原GD赋值顺序。
Status emit_choice(ProjectionWriter& out,const FamilyChoice& f,bool fact){out.field("guardian_actor_id",f.guardian_actor_id);out.field("heir_actor_id",f.heir_actor_id);out.field("adoption_source",f.adoption_source);out.field("place_id",f.place_id);if(f.designation_source)out.field("designation_source",*f.designation_source);if(f.assets)out.object("assets",[&](auto& w){return emit_assets(w,*f.assets);});if(fact){out.field("kind",f.kind);out.field("tick",f.tick);}return out.order_fields(f.field_order);}
BoundaryValue encode_choice(const FamilyChoice& f,bool fact){return family_projection::encode([&](auto& out){return emit_choice(out,f,fact);});}
// 业务比较只比较实际typed条款；冷字段序不影响授权或报价新鲜度。
bool same_policy(const FamilyPolicy& a,const FamilyPolicy& b){return a.child_age_years==b.child_age_years&&a.guardian_min_age==b.guardian_min_age&&a.heir_min_age==b.heir_min_age&&a.retirement_min_age==b.retirement_min_age&&a.enable_travel_plan==b.enable_travel_plan;}
bool same_terms(const AdoptionTerms& a,const AdoptionTerms& b){return a.guardian_actor_id==b.guardian_actor_id&&a.provider_actor_id==b.provider_actor_id&&a.role_id==b.role_id&&a.place_id==b.place_id&&a.prototype_id==b.prototype_id&&a.display_name==b.display_name&&a.birth_tick==b.birth_tick&&a.duration==b.duration&&a.fee==b.fee&&a.payer_wallet_id==b.payer_wallet_id&&a.recipient_wallet_id==b.recipient_wallet_id&&same_policy(a.policy,b.policy);}
bool same_choice(const FamilyChoice& a,const FamilyChoice& b){if(a.guardian_actor_id!=b.guardian_actor_id||a.heir_actor_id!=b.heir_actor_id||a.adoption_source!=b.adoption_source||a.place_id!=b.place_id||a.designation_source!=b.designation_source||a.assets.has_value()!=b.assets.has_value())return false;if(!a.assets)return true;const auto& x=*a.assets;const auto& y=*b.assets;if(x.disabled_roles!=y.disabled_roles||x.wallets.size()!=y.wallets.size()||x.goods.size()!=y.goods.size()||x.estates.size()!=y.estates.size())return false;for(std::size_t i=0;i<x.wallets.size();++i)if(x.wallets[i].source_id!=y.wallets[i].source_id||x.wallets[i].destination_id!=y.wallets[i].destination_id||x.wallets[i].amount!=y.wallets[i].amount)return false;for(std::size_t i=0;i<x.goods.size();++i)if(x.goods[i].source_inventory_id!=y.goods[i].source_inventory_id||x.goods[i].destination_inventory_id!=y.goods[i].destination_inventory_id||x.goods[i].lot_id!=y.goods[i].lot_id||x.goods[i].item_id!=y.goods[i].item_id||x.goods[i].quantity!=y.goods[i].quantity)return false;for(std::size_t i=0;i<x.estates.size();++i)if(x.estates[i].estate_id!=y.estates[i].estate_id||x.estates[i].inventory_id!=y.estates[i].inventory_id||x.estates[i].wallet_id!=y.estates[i].wallet_id)return false;return true;}
