    if(const auto* control=selected.find("household_control")){if(!selected.find("dynamic_world"))fail("HouseholdControlNativeProfileRequired",scenario);auto decoded=decode_household_control_catalog(*control);if(!decoded.ok)return {false,{},decoded.error};out.household_control=std::move(decoded.value);}
    if(const auto* config=selected.find("adult_adoption")){if(!selected.find("dynamic_world"))fail("AdultAdoptionNativeProfileRequired",scenario);auto decoded=decode_adult_adoption_request_catalog(*config,field(data,"adult_adoption_requests","data"));if(!decoded.ok)return {false,{},decoded.error};out.adult_adoption=std::move(decoded.value);}
